import {componentDefinitions} from './scene-components.js';
const safeKey=k=>(typeof k==='string'||Number.isInteger(k))&&!['__proto__','prototype','constructor'].includes(String(k));
export function validPrefabExtension(data){return (data.parent===undefined||typeof data.parent==='string'&&(!data.parent||/^Assets\/.+\.hbprefab\.json$/.test(data.parent))&&!data.parent.includes('..'))&&(data.removed===undefined||Array.isArray(data.removed)&&data.removed.every(id=>typeof id==='string'))&&(data.overrides===undefined||Array.isArray(data.overrides)&&data.overrides.length<=100000&&data.overrides.every(o=>typeof o?.object==='string'&&Array.isArray(o.path)&&o.path.length>0&&o.path.length<=32&&o.path.every(safeKey)&&!['id','parent','parentId'].includes(o.path[0])&&Object.hasOwn(o,'value')));}
export function setPrefabOverride(data,object,path,value){const override={object,path,value:structuredClone(value)};if(!validPrefabExtension({...data,overrides:[override]}))throw Error('프리팹 오버라이드 경로 오류');data.overrides??=[];const index=data.overrides.findIndex(o=>o.object===object&&JSON.stringify(o.path)===JSON.stringify(path));if(index<0)data.overrides.push(override);else data.overrides[index]=override;return data;}
export function revertPrefabOverride(data,object,path){data.overrides=(data.overrides||[]).filter(o=>!(o.object===object&&JSON.stringify(o.path)===JSON.stringify(path)));return data;}
export async function resolvePrefab(path,read,{validate,stack=[]}={}){
  if(stack.includes(path)||stack.length>=16)throw Error('프리팹 상속·중첩 순환: '+[...stack,path].join(' → '));const data=structuredClone(await read(path));if(!validPrefabExtension(data)||validate&&!validate(data))throw Error('프리팹 검증 실패: '+path);const chain=[...stack,path];let objects=data.parent?structuredClone((await resolvePrefab(data.parent,read,{validate,stack:chain})).objects):[];
  for(const object of data.objects||[]){const index=objects.findIndex(o=>o.id===object.id);if(index>=0)objects[index]=object;else objects.push(object);}const removed=new Set(data.removed||[]);let count;do{count=removed.size;for(const o of objects)if(removed.has(o.parent||o.parentId))removed.add(o.id);}while(count!==removed.size);objects=objects.filter(o=>!removed.has(o.id));
  const deferred=[];const apply=override=>{const owner=objects.find(o=>o.id===override.object);if(!owner)throw Error('오버라이드 대상이 없어요: '+override.object);let at=owner;for(const key of override.path.slice(0,-1)){if(!at||!Object.hasOwn(at,key)||typeof at[key]!=='object')throw Error('오버라이드 속성 경로가 없어요.');at=at[key];}if(!at||typeof at!=='object')throw Error('오버라이드 대상 속성 오류');const leaf=override.path.at(-1);if(Array.isArray(at)&&(!Number.isInteger(leaf)||leaf<0||leaf>=at.length))throw Error('오버라이드 배열 범위를 확인하세요.');at[leaf]=structuredClone(override.value);};for(const override of data.overrides||[]){if(objects.some(o=>o.id===override.object))apply(override);else deferred.push(override);}
  for(const anchor of [...objects])if(anchor.nestedPrefab){const nested=await resolvePrefab(anchor.nestedPrefab,read,{validate,stack:chain}),ids=new Map(nested.objects.map(o=>[o.id,anchor.id+'/'+o.id]));for(const source of nested.objects){const o=structuredClone(source);o.id=ids.get(source.id);o.parent=source.id===nested.root?anchor.id:ids.get(source.parent||source.parentId);delete o.parentId;for(const key of ['owner','controller','pawn'])if(ids.has(o[key]))o[key]=ids.get(o[key]);for(const c of o.components||[])for(const [key,field] of Object.entries(componentDefinitions[c.type]?.properties||{}))if(field.objectReference&&ids.has(c.properties?.[key]))c.properties[key]=ids.get(c.properties[key]);objects.push(o);}}
  for(const override of deferred)apply(override);
  const result={...data,parent:'',objects,overrides:[],removed:[]};if(validate&&!validate(result))throw Error('프리팹 해석 결과 검증 실패: '+path);return result;
}
